// 1. Kiểm tra Status code là 201
pm.test("Status code is 201", function () {
    pm.response.to.have.status(201);
});

// 2. Kiểm tra name và job khớp với dữ liệu đã gửi
pm.test("Validate name and job match request data", function () {
    var responseData = pm.response.json();
    pm.expect(responseData.name).to.eql(pm.environment.get("name"));
    pm.expect(responseData.job).to.eql(pm.environment.get("job"));
});

// 3. Trích xuất id trả về và gán vào biến môi trường userId
pm.test("Extract userId to environment", function () {
    var responseData = pm.response.json();
    if (responseData.id) {
        pm.environment.set("userId", responseData.id);
    }
});

// Khai báo 3 dòng dữ liệu thay cho file CSV
var testData = [
    { name: "An Nguyen", job: "QA Lead" },
    { name: "Bao Tran", job: "Automation Tester" },
    { name: "Chi Le", job: "Software Engineer" }
];

// Lấy chỉ số lần chạy tự động hoặc mặc định dòng đầu tiên
var iteration = pm.info.iteration || 0;
var currentData = testData[iteration % testData.length];

// Gán dữ liệu vào biến môi trường để Body nhận diện {{name}} và {{job}}
pm.environment.set("name", currentData.name);
pm.environment.set("job", currentData.job);

// 1. Kiểm tra Status code là 200
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// 2. Kiểm tra trường data.id bằng 2 và kiểm tra data.email chứa đuôi @reqres.in
pm.test("Validate user id is 2 and email domain is reqres.in", function () {
    var responseData = pm.response.json();
    
    // Kiểm tra id trong đối tượng data bằng 2
    pm.expect(responseData.data.id).to.eql(2);
    
    // Kiểm tra email chứa đuôi @reqres.in
    pm.expect(responseData.data.email).to.include("@reqres.in");
});

// 1. Kiểm tra Status code là 200
pm.test("Status code is 200", function () {
