});

// 2. Kiểm tra trường updatedAt tồn tại trong response body
pm.test("Validate updatedAt field exists", function () {
    var responseData = pm.response.json();
    pm.expect(responseData).to.have.property("updatedAt");
});

// Kiểm tra Status code là 204 (No Content)
pm.test("Status code is 204", function () {
